#!/bin/bash
set -e
pnpm install --frozen-lockfile

# Apply pending Drizzle migrations from lib/db/drizzle/ (generated by
# `pnpm --filter @workspace/db run generate`). Tracked in
# drizzle.__drizzle_migrations. Drizzle is the single source of truth for
# schema changes — every change in lib/db/src/schema/ should be committed
# alongside a generated .sql file.
pnpm --filter @workspace/db run migrate
